import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem131 preserva oferta e afiliado',()=>{for(const [id,titulo,expected,link] of [["r7HSFtoP8OEdijhRMIDk","Carretilha Molinete Pesca,18+1 Rolamentos 7.2:1 Pescaria","Carretilha de pesca — relação 7,2:1 anunciada","https://produto.mercadolivre.com.br/MLB-4839780461-carretilha-molinete-pesca181-rolamentos-721-pescaria-_JM?searchVariation=197263205538"],["rfym6WivFVhxpwn2WF6r","Winleve Studio Otimizador Windows 10 E 11 Digital","Winleve Studio Otimizador Windows 10 E 11 Digital","https://www.mercadolivre.com.br/up/MLBU4707774752?pdp_filters=item_id%3AMLB5046495691"],["RHhkWKxMXBZONt8jx4Ew","Computador Completo 20'' BRX Intel Core i5 6ª Geração 8GB SSD 256GB Monitor LED 75Hz Windows Teclado Mouse Kit Completo Desktop Office Home Office Estudo Trabalho","Computador BRX Core i5-6500 — 8 GB e SSD de 256 GB anunciados","https://www.mercadolivre.com.br/p/MLB80104605?wid=MLB7777101942"]]){const p={id,titulo,link,linkAfiliado:'https://meli.la/preservar',preco:'preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.titulo,expected);for(const k of ['id','link','linkAfiliado','preco'])assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);}});
